						dshj_VIPolPot: ['male', 'western', 3, ['dshj_jiduan'], ['des:波尔布特,民主柬埔寨红色高棉最高领导人……']],
						dshj_VIxiangshen: ['male', 'western', 4, ['dshj_tiangou', 'dshj_fuzheng', 'dshj_VIroulin'], ['des:乡绅,也许是一个很神秘的人,也许只是一个普通的伪君子,在他的身上,有着许多神秘的属性……']],
						//异界之赐
						dshj_VIOdimm: ['male', 'shen', 1, ['dshj_moti', 'dshj_xueqi'], ['des:欧迪姆,又名镜子大师,来自游戏<巫师3:石之心>……']],
						dshj_VISerana: ['female', 'shen', 3, ['dshj_anyi', 'dshj_guixi'], ['des:瑟拉娜,游戏<上古卷轴5:天际>DLC<黎明守卫>剧情的核心人物,她是一名诺德吸血鬼,是哈孔与贝蕾莉卡的女儿……']],
						dshj_VIWeiShen: ['male', 'shen', '4/5', ['dshj_jianshen', 'dshj_jianqu', 'dshj_chaowei', 'dshj_qianjing'], ['des:沈威,卧底警察,来自游戏<热血无赖>……']],
