						dshj_VIhudieren: ['female', 'shen', 3, ['dshj_jiaoren', 'dshj_diewu', 'dshj_yinren'], ['des:蝴蝶忍,来自动漫<鬼灭之刃>及其衍生作品……']],
						dshj_VIjiegeng: ['female', 'shen', 4, ['dshj_VIyugao'], ['des:桔梗,守护四魂之玉的巫女,犬夜叉的前女友,来自漫画<犬夜叉>及其衍生作品……']],
						dshj_VIlingyuexianji: ['female', 'shen', 4, ['dshj_VIyugao'], ['des:凌月仙姬,斗牙王的正妻,杀生丸的母亲,来自漫画<犬夜叉>及其衍生作品……']],
						dshj_VIquanyecha: ['male', 'shen', 5, ['dshj_VIyugao'], ['des:犬夜叉,斗牙王的半妖儿子,来自漫画<犬夜叉>及其衍生作品……']],
						dshj_VIshashengwan: ['male', 'shen', 6, ['dshj_VIyugao'], ['des:杀生丸,犬夜叉同父异母的哥哥,来自漫画<犬夜叉>及其衍生作品……']],
						dshj_VIweierxun: ['male', 'shen', 3, ['dshj_kexue', 'dshj_liandong'], ['des:威尔逊,来自游戏<饥荒>……']],
						//传说之契
						dshj_VIfanen: ['male', 'shen', 3, ['dshj_lieshou', 'dshj_liehun', 'dshj_songzang'], ['des:凡恩,MOBA游戏<传说对决>中的射手类英雄……']],
						dshj_VIhaiya: ['male', 'shen', 3, ['dshj_anhen', 'dshj_zhouying', 'dshj_yingbu', 'dshj_wanxiang'], ['des:亥犽,MOBA游戏<传说对决>中的射手类英雄……']],
